 private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
 private void watch(ContentItem item){watch(item,true);}
 private void watch(ContentItem item,boolean resume){
  buildWatchUi(item);int request=generation;
  io.execute(()->{try{PlaybackInfo loaded=api.resolve(item);main.post(()->{if(request!=generation)return;info=loaded;if(current.user.isEmpty()&&ServiceUrls.userId(loaded.user))current=new ContentItem(item.id,loaded.user,item.title,item.nick,item.thumb,item.viewers,item.vod);startPlayer(item,request,resume);});}catch(Exception e){main.post(()->{if(request!=generation)return;playbackStatus.setText(e instanceof org.json.JSONException||e.getMessage()==null?"재생 정보를 확인할 수 없습니다":e.getMessage());LinearLayout error=column();note(error,"로그인 상태·시청 권한을 확인하거나 공식 화면에서 재생해 보세요.");error.addView(button("로그인 / 인증",()->officialLogin()));error.addView(button("다시 시도",()->watch(item,resume)));error.addView(button("공식 화면 열기",()->official(item.pageUrl(),"공식 재생 화면")));watch.video.addView(error);});}});
 }
