  TextView title=text(html(item.title),18,Color.WHITE);title.setTypeface(null,Typeface.BOLD);title.setMaxLines(2);title.setPadding(dp(16),dp(12),dp(16),dp(8));watch.details.setBackgroundColor(bg);watch.details.addView(title);LinearLayout who=row();who.setPadding(dp(14),0,dp(10),dp(8));TextView name=text((item.vod?"VOD":"● LIVE")+"  "+html(item.nick.isEmpty()?item.user:item.nick),14,muted);who.addView(name,new LinearLayout.LayoutParams(0,-2,1));who.addView(button("방송국",()->{if(current!=null)station(current.user,"review");}));who.addView(button("☆",()->{if(current!=null)favorite(current.user);}));watch.details.addView(who);
