  chatStatus=text("채팅 연결 중…",11,muted);chatStatus.setPadding(dp(10),dp(2),dp(10),dp(2));watch.chat.addView(chatStatus);chatList=new RecyclerView(this);chatList.setLayoutManager(new LinearLayoutManager(this));chatRows=new ChatRows();chatList.setAdapter(chatRows);watch.chat.addView(chatList,new LinearLayout.LayoutParams(-1,0,1));
