 private void setPlaybackControlsVisible(boolean visible){if(playerChrome!=null)playerChrome.setVisibility(visible?View.VISIBLE:View.GONE);if(chatHeader!=null)chatHeader.setVisibility(!full||visible?View.VISIBLE:View.GONE);}
