 private void updatePipParams(){if(Build.VERSION.SDK_INT<26||player==null)return;android.app.PictureInPictureParams.Builder b=new android.app.PictureInPictureParams.Builder().setAspectRatio(new android.util.Rational(16,9));if(Build.VERSION.SDK_INT>=31)b.setAutoEnterEnabled(player.isPlaying());setPictureInPictureParams(b.build());}
 private void enterPip(){if(Build.VERSION.SDK_INT<26){toast("작은 화면은 Android 8.0 이상에서 사용할 수 있습니다");return;}if(player==null||!player.isPlaying()){toast("영상을 재생 중일 때 사용할 수 있습니다");return;}pipRequested=true;try{android.app.PictureInPictureParams.Builder b=new android.app.PictureInPictureParams.Builder().setAspectRatio(new android.util.Rational(16,9));if(Build.VERSION.SDK_INT>=31)b.setAutoEnterEnabled(true);enterPictureInPictureMode(b.build());}catch(IllegalStateException e){pipRequested=false;toast("작은 화면 전환을 시작할 수 없습니다");}}
 @Override public void onUserLeaveHint(){super.onUserLeaveHint();if(Build.VERSION.SDK_INT>=26&&player!=null&&player.isPlaying()){pipRequested=true;if(Build.VERSION.SDK_INT<31)enterPip();}}
 @Override public void onPictureInPictureModeChanged(boolean inPictureInPictureMode,Configuration newConfig){super.onPictureInPictureModeChanged(inPictureInPictureMode,newConfig);pipMode=inPictureInPictureMode;pipRequested=inPictureInPictureMode;if(watch!=null){watch.pictureInPicture=inPictureInPictureMode;watch.requestLayout();}if(inPictureInPictureMode){root.setPadding(0,0,0,0);if(playerView!=null)playerView.hideController();setPlaybackControlsVisible(false);}else if(watch!=null)setPlaybackControlsVisible(!full);root.requestApplyInsets();}
