 @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus&&full)applyImmersive();}
 private final Runnable vodTick=new Runnable(){public void run(){if(player==null||info==null||current==null||!current.vod)return;updateVodChat();main.postDelayed(this,500);}};
 private void updateVodChat(){
  int part=player.getCurrentMediaItemIndex();long pos=player.getCurrentPosition();if(part<0||part>=info.chat.size())return;String url=info.chat.get(part);if(url.isEmpty()){chatStatus.setText("이 영상에는 제공되는 다시보기 채팅이 없습니다");return;}
  long chunk=ChatTimeline.chunkStart(pos,info.chatSeconds);String key=part+":"+chunk;List<ChatMessage> messages=chatCache.get(key);
  if(messages==null){if(key.equals(chatFailed)){chatStatus.setText("채팅을 불러오지 못했습니다 · 화면을 다시 열면 재시도합니다");return;}if(!key.equals(chatLoading)){chatLoading=key;chatStatus.setText("재생 위치의 채팅 불러오는 중…");int request=generation;String referer=current.pageUrl();io.execute(()->{try{List<ChatMessage> found=ChatParser.xml(api.text(url+(url.contains("?")?"&":"?")+"startTime="+chunk,null,referer));main.post(()->{if(request!=generation)return;chatCache.put(key,found);if(chatCache.size()>8)chatCache.remove(chatCache.keySet().iterator().next());if(key.equals(chatLoading))chatLoading="";});}catch(Exception e){main.post(()->{if(request!=generation)return;chatFailed=key;if(key.equals(chatLoading))chatLoading="";});}});}return;}
  List<ChatMessage> visible=ChatTimeline.visible(messages,pos);String signature=key+":"+visible.size()+":"+(visible.isEmpty()?"":visible.get(visible.size()-1).timeMs+visible.get(visible.size()-1).text);
  if(!signature.equals(chatSignature)){chatRows.replace(visible);chatSignature=signature;chatList.scrollToPosition(Math.max(0,visible.size()-1));}chatStatus.setText("다시보기 채팅 · 영상 위치와 동기화 · 읽기 전용");
 }
 private final class ChatRows extends RecyclerView.Adapter<ChatHolder>{
  final List<ChatMessage> messages=new ArrayList<>();
  public ChatHolder onCreateViewHolder(ViewGroup p,int t){LinearLayout line=row();line.setGravity(Gravity.TOP);line.setPadding(dp(10),dp(6),dp(10),dp(6));TextView nick=text("",12,muted),message=text("",13,Color.WHITE);nick.setMaxLines(2);nick.setEllipsize(android.text.TextUtils.TruncateAt.END);line.addView(nick,new LinearLayout.LayoutParams(0,-2,.34f));line.addView(message,new LinearLayout.LayoutParams(0,-2,.66f));return new ChatHolder(line,nick,message);}
  public void onBindViewHolder(ChatHolder holder,int n){ChatMessage m=messages.get(n);holder.nick.setText(m.nick);holder.message.setText(m.text);}
  public int getItemCount(){return messages.size();}
  void append(List<ChatMessage> batch){messages.addAll(batch);if(messages.size()>200)messages.subList(0,messages.size()-200).clear();notifyDataSetChanged();}void replace(List<ChatMessage> batch){messages.clear();messages.addAll(batch);notifyDataSetChanged();}
 }
 private static final class ChatHolder extends RecyclerView.ViewHolder{final TextView nick,message;ChatHolder(View row,TextView nick,TextView message){super(row);this.nick=nick;this.message=message;}}
 private final Runnable historyTick=new Runnable(){public void run(){if(player==null||current==null||!current.vod)return;if(player.isPlaying())savePlayback();main.postDelayed(this,5000);}};
 private void savePlayback(){
  if(player==null||current==null||!current.vod||info==null||!historyStarted||player.getPlayerError()!=null)return;
  int part=player.getCurrentMediaItemIndex();if(part<0||part>=info.media.size())return;
  long pos=Math.max(0,player.getCurrentPosition()),elapsed=pos,total=0;boolean known=info.durations.size()==info.media.size();
  for(int i=0;i<info.durations.size();i++){long duration=info.durations.get(i);if(duration<=0)known=false;total+=duration;if(i<part)elapsed+=duration;}
  ContentItem metadata=new ContentItem(current.id,current.user,info.title.isEmpty()?current.title:info.title,current.nick,current.thumb,"",true);
  history.save(new WatchHistory.Entry(metadata,part,pos,known?total:0,elapsed,System.currentTimeMillis(),player.getPlaybackState()==Player.STATE_ENDED));
 }
 private void releaseWatch(){qualityRequest++;savePlayback();historyStarted=false;main.removeCallbacks(historyTick);saveChat();main.removeCallbacks(vodTick);if(liveChat!=null){liveChat.close();liveChat=null;}if(player!=null){player.release();player=null;playerView=null;}info=null;current=null;watch=null;chatCache.clear();chatLoading="";chatFailed="";chatSignature="";}
